import matplotlib.pyplot as plt
import matplotlib.patches as patches
import numpy as np
import re
from typing import Optional, Dict, List, Tuple, Any

def _show_or_close_figure() -> None:
    """Show figures on interactive backends and close on agg-like backends."""
    backend = (plt.get_backend() or "").lower()
    if "agg" in backend:
        plt.close()
    else:
        plt.show()


