# PCT layer type classification and colors
_PCT_LAYER_COLORS = {
    'input':       '#D8BFD8',   # light purple
    'perception':  '#ADD8E6',   # light blue
    'reference':   '#FF0000',   # red
    'comparator':  '#FFBF00',   # amber
    'output':      '#008000',   # green
    'actions':     '#FFFF00',   # yellow
    'errors':      '#FFFF00',   # yellow
    'other':       '#808080',   # grey
}


def _classify_layer(layer_name: str) -> str:
    """Classify a Keras layer name into a PCT function type."""
    name = layer_name.strip()
    if name in ('Observations', 'ReferencesInput'):
        return 'input'
    if re.match(r'^PL\d+', name):
        return 'perception'
    if re.match(r'^RL\d+', name):
        return 'reference'
    if re.match(r'^CL\d+', name):
        return 'comparator'
    if re.match(r'^OL\d+', name):
        return 'output'
    if name.startswith('Actions'):
        return 'actions'
    if name == 'Errors':
        return 'errors'
    return 'other'


def _get_layer_info(model) -> List[Dict[str, Any]]:
    """Extract layer names, types and output sizes from a compiled Keras model.

    Returns a list of dicts with keys: name, type, units, pct_type, color.
    Input layers are listed first, followed by layers in topological order.
    Utility layers (Concatenate, Activation used only for renaming) are
    included so the diagram mirrors ``model.summary()`` faithfully.
    """
    info: List[Dict[str, Any]] = []
    for layer in model.layers:
        name = layer.name
        layer_type = type(layer).__name__

        # Determine number of "nodes" to display
        # Use layer.output.shape (Keras 3.x); fall back to layer.output_shape
        try:
            out_shape = tuple(layer.output.shape)
        except (AttributeError, RuntimeError):
            out_shape = layer.output_shape
        if isinstance(out_shape, list):
            out_shape = out_shape[0]  # multi-output: take first
        units = out_shape[-1] if out_shape and len(out_shape) > 1 else 1

        pct_type = _classify_layer(name)
        color = _PCT_LAYER_COLORS.get(pct_type, _PCT_LAYER_COLORS['other'])

        info.append({
            'name': name,
            'type': layer_type,
            'units': units,
            'pct_type': pct_type,
            'color': color,
        })
    return info


def _get_model_edges(model) -> List[Tuple[str, str]]:
    """Extract directed ``(source_name, target_name)`` edges from a Keras Functional model.

    Works by matching the Python identity of each layer's input tensors
    against the output tensors of all layers in the model.
    """
    # Map each output tensor's id to the producing layer's name
    output_map: Dict[int, str] = {}
    for layer in model.layers:
        try:
            out = layer.output
            for o in (out if isinstance(out, list) else [out]):
                output_map[id(o)] = layer.name
        except (AttributeError, RuntimeError):
            pass

    edges: List[Tuple[str, str]] = []
    for layer in model.layers:
        try:
            inp = layer.input
        except (AttributeError, RuntimeError):
            continue
        for t in (inp if isinstance(inp, list) else [inp]):
            src = output_map.get(id(t))
            if src is not None and src != layer.name:
                edges.append((src, layer.name))
    return edges

# %% ../nbs/03_visualization.ipynb #b1f527ee
def draw_traditional_nn(
    individual,                         # DHPCTIndividual (must be compiled) or a Keras Model
    filename: Optional[str] = None,     # output image path (None = don't save)
    title: str = 'DHPCTIndividual',     # figure title
    width_scale: float = 2.5,           # horizontal spacing between grid columns
    height_scale: float = 2.0,          # vertical spacing between grid rows
    circle_size: float = 0.5,           # node circle radius
    line_thickness: float = 1.0,        # connection line width
    show_legend: bool = True,           # display colour legend
    expand_units: bool = False,         # draw one circle per unit when True
    dpi: int = 150,                     # output resolution
    circle_label_fontsize: Optional[int] = 10,  # circle label font size (None = auto)
    show_weights: bool = False,         # show weight values on connections (expand_units only)
    weight_fontsize: Optional[int] = 9,  # weight label font size (None = auto)
    bottom_label_fontsize: int = 6,     # bottom metadata label font size
    legend_fontsize: int = 9,           # legend label font size
    legend_title_fontsize: int = 10,    # legend title font size
    show_unit_labels: bool = True,      # show unit labels inside expanded nodes
    show_refin_values: bool = True,     # show ReferencesInput node values
    refin_values: Optional[List[float]] = None,  # optional explicit ReferencesInput values
    show_smooth_factors: bool = True,   # show alpha (smooth_factor) on ExponentialSmoothLayer nodes
    smooth_factor_decimals: int = 2,    # number of decimals to display for smooth_factor
    smooth_factor_fontsize: Optional[int] = 9,  # font size for smooth_factor labels (None = auto)
    collapse_smooth_pairs: bool = True, # merge Dense/EWML + ExponentialSmoothLayer pairs into one node
):
    """Draw a DHPCTIndividual's compiled Keras model on a structured grid.

    Layers are placed on a grid whose columns run left-to-right (one pair of
    columns per PCT level, lowest level on the left) and rows run
    top-to-bottom:

    * **Row 1** - Observations (col 1), Perception layers (odd cols from 3)
    * **Row 2** - Output layers (even cols from 2), Comparator layers (odd cols from 3)
    * **Row 3** - Reference layers (odd cols from 3)
    * **Row 4** - Actions (one col past highest PL)
    * **Row 5** - ReferencesInput (col 1), Errors (same col as Actions)

    Connections are drawn as straight lines.

    Parameters
    ----------
    individual : DHPCTIndividual or keras.Model
        A compiled individual (uses ``individual.model``) or a raw Keras model.
    filename : str or None
        File path for the saved image.
        If *None* the figure is returned without saving.
    title : str
        Title displayed above the diagram.
    width_scale : float
        Horizontal spacing multiplier between grid columns.
    height_scale : float
        Vertical spacing multiplier between grid rows.
    circle_size : float
        Radius of each node circle.
    line_thickness : float
        Width of connection lines.
    show_legend : bool
        If True, add a colour legend for PCT layer types.
    expand_units : bool
        If False (default), draw one circle per layer.
        If True, draw one circle per output unit in each layer.
    dpi : int
        Resolution of the saved image.
    circle_label_fontsize : int or None
        Font size for circle labels. If None, auto-calculated from circle_size.
    show_weights : bool
        If True and *expand_units* is True, display the weight value on
        each unit-to-unit connection.
    weight_fontsize : int or None
        Font size for weight labels. If None, auto-calculated from
        *circle_size*.
    bottom_label_fontsize : int
        Font size for per-node bottom metadata labels such as
        ``(Dense, 1)``.
    legend_fontsize : int
        Font size for legend entries.
    legend_title_fontsize : int
        Font size for the legend title.
    show_unit_labels : bool
        If True (default), render per-unit labels in expanded diagrams.
    show_refin_values : bool
        If True (default), annotate expanded ``ReferencesInput`` unit nodes
        with numeric values.
    refin_values : list[float] or None
        Optional values for ``ReferencesInput`` units. If None, values
        default to zeros of matching size.
    show_smooth_factors : bool
        If True (default), annotate ``ExponentialSmoothLayer`` nodes with
        their ``smooth_factor`` (α) values.  In ``expand_units`` mode each
        unit's α is rendered as a small text below its circle; in collapsed
        mode the α is appended to the layer's bottom ``(type, units)`` label.
    smooth_factor_decimals : int
        Number of decimal places used when rendering α values (default 2).
    smooth_factor_fontsize : int or None
        Font size for the per-unit α annotations when ``expand_units`` is
        True.  If None, auto-calculated from *circle_size*.
    collapse_smooth_pairs : bool
        If True (default), each ``X`` (Dense / ElementWiseMultiplyLayer)
        immediately followed by ``X_smooth`` (ExponentialSmoothLayer) is
        rendered as a single node.  The merged node keeps the ``X_smooth``
        display name (so the ``_smooth`` suffix is preserved), shows the
        underlying ``X`` weights, and shows the ``X_smooth`` α on its
        existing label.  Set False to keep the original two-node behaviour
        (one circle for ``X`` and one for ``X_smooth``).

    Returns
    -------
    fig : matplotlib.figure.Figure
        The matplotlib figure object.
    """
    model = getattr(individual, 'model', individual)
    if model is None:
        raise ValueError(
            "Individual is not compiled.  Call individual.compile() first."
        )

    def _unit_label(layer_name: str, unit_idx: int) -> Optional[str]:
        """Return per-unit labels for control layers like P00C00, C00C01, etc."""
        m = re.match(r'^(PL|CL|RL|OL)(\d+)', layer_name)
        if not m:
            return None
        prefix = {'PL': 'P', 'CL': 'C', 'RL': 'R', 'OL': 'O'}[m.group(1)]
        return f"{prefix}{int(m.group(2)):02d}C{unit_idx:02d}"

    def _unit_edge_pairs(src_name: str, dst_name: str) -> List[Tuple[Any, Any]]:
        """Return concrete unit-to-unit edge pairs for one layer-level edge."""
        src_keys = layer_node_keys[src_name]
        dst_keys = layer_node_keys[dst_name]
        src_units = len(src_keys)
        dst_units = len(dst_keys)

        dst_type = layer_map.get(dst_name, {}).get('type', '')
        # When a Dense/EWML -> smooth pair is collapsed, incoming A -> Dense
        # edges are rewritten as A -> smooth.  Route those incoming edges using
        # the absorbed source layer's semantics, not the smooth layer's
        # one-to-one semantics.  Otherwise dense perception inputs such as
        # Observations -> PL00_smooth are drawn as Obs0->P00C00 and
        # Obs1->P00C01 instead of all observations feeding every P00 unit.
        absorbed_source = smooth_pair_sources.get(dst_name)
        if absorbed_source is not None and src_name != absorbed_source:
            dst_type = layer_map.get(absorbed_source, {}).get('type', dst_type)

        one_to_one_ops = {'Subtract', 'ElementWiseMultiplyLayer', 'Multiply', 'Add',
                          'ExponentialSmoothLayer'}

        # Element-wise layers map index-to-index when dimensions align.
        if dst_type in one_to_one_ops and src_units == dst_units:
            return [(src_keys[i], dst_keys[i]) for i in range(src_units)]

        # Single-unit endpoints naturally fan in/out.
        if src_units == 1:
            return [(src_keys[0], dk) for dk in dst_keys]
        if dst_units == 1:
            return [(sk, dst_keys[0]) for sk in src_keys]

        # Dense-style default: every source unit connects to every target unit.
        return [(sk, dk) for sk in src_keys for dk in dst_keys]

    def _get_connection_weight(dst_name, src_unit, dst_unit):
        """Return the weight value for a unit-to-unit connection, or None.

        When the destination is a smooth layer that absorbed a paired
        Dense / ElementWiseMultiplyLayer source (``smooth_pair_sources``
        maps smooth_name → source_name), the weight lookup falls through
        to the source's kernel so the merged node still exposes its
        incoming edge weights.
        """
        try:
            dst_layer = model.get_layer(dst_name)
        except ValueError:
            return None
        w = dst_layer.get_weights()
        layer_type = type(dst_layer).__name__
        # If this smooth layer absorbed a weighted source, defer to that
        # source's kernel for the weight annotation.
        source_name = smooth_pair_sources.get(dst_name)
        if source_name is not None and (not w or layer_type == 'ExponentialSmoothLayer'):
            try:
                src_layer = model.get_layer(source_name)
            except ValueError:
                return None
            w = src_layer.get_weights()
            if not w:
                return None
            layer_type = type(src_layer).__name__
        else:
            if not w:
                return None
        if layer_type == 'Dense':
            kernel = w[0]
            if src_unit < kernel.shape[0] and dst_unit < kernel.shape[1]:
                return float(kernel[src_unit, dst_unit])
        elif layer_type == 'ElementWiseMultiplyLayer':
            ow = w[0]
            if dst_unit < ow.shape[0]:
                return float(ow[dst_unit])
        return None

    def _get_smooth_factors(layer_name: str, units: int) -> Optional[List[float]]:
        """Return per-unit ``smooth_factor`` values for an ExponentialSmoothLayer.

        Returns ``None`` if the layer is not an ``ExponentialSmoothLayer`` or
        has no weights.  Scalar smooth_factors are broadcast to a list of the
        requested length.
        """
        try:
            layer = model.get_layer(layer_name)
        except ValueError:
            return None
        if type(layer).__name__ != 'ExponentialSmoothLayer':
            return None
        w = layer.get_weights()
        if not w:
            return None
        sf = np.asarray(w[0]).reshape(-1)
        if sf.shape[0] == 1:
            return [float(sf[0])] * max(1, units)
        return [float(v) for v in sf[:max(1, units)]]

    def _smooth_label(name: str, layer_units: int) -> Optional[str]:
        """Build the smooth-factor annotation text for a non-expanded layer."""
        sfs = _get_smooth_factors(name, layer_units)
        if sfs is None:
            return None
        if len(sfs) == 1 or all(abs(sfs[0] - s) < 1e-9 for s in sfs):
            return f"α={sfs[0]:.{smooth_factor_decimals}f}"
        return "α=[" + ",".join(f"{v:.{smooth_factor_decimals}f}" for v in sfs) + "]"

    def _detect_smooth_pairs():
        """Detect ``X`` -> ``X_smooth`` pairs to collapse when ``collapse_smooth_pairs=True``.

        Returns a mapping ``{smooth_name: source_name}``.  The source must
        exist in the model, must be a ``Dense`` or
        ``ElementWiseMultiplyLayer`` layer, and its only consumer must be the
        paired ``ExponentialSmoothLayer``.  Pairs whose source is also a
        ``_smooth`` or ``_sigmoid`` suffix layer are skipped (nested
        activations are not yet supported).
        """
        pairs = {}
        # First pass: identify the immediate consumer of each layer.
        consumer_of = {li['name']: [] for li in layer_info}
        for src, dst in edges:
            if src in consumer_of:
                consumer_of[src].append(dst)

        smooth_types = {'ExponentialSmoothLayer'}
        mergeable_source_types = {'Dense', 'ElementWiseMultiplyLayer'}
        for li in layer_info:
            name = li['name']
            li_type = li['type']
            if li_type not in smooth_types:
                continue
            if not name.endswith('_smooth'):
                continue
            source_name = name[:-len('_smooth')]
            if source_name not in layer_map:
                continue
            if layer_map[source_name]['type'] not in mergeable_source_types:
                continue
            consumers = consumer_of.get(source_name, [])
            if consumers != [name]:
                # Only collapse when the source is dedicated to this smooth layer.
                continue
            pairs[name] = source_name
        return pairs

    def _get_kernel_summary(layer_name):
        """Return a compact text summary of a Dense/EWML kernel for display."""
        try:
            layer = model.get_layer(layer_name)
        except ValueError:
            return None
        w = layer.get_weights()
        if not w:
            return None
        kernel = np.asarray(w[0])
        flat = kernel.reshape(-1)
        if flat.size <= 4:
            vals = ', '.join(f'{v:.2f}' for v in flat)
            return f'w=[{vals}]'
        if kernel.ndim == 1:
            head = ', '.join(f'{v:.2f}' for v in flat[:4])
            return f'w=[{head}, ...]'
        return f'W{tuple(kernel.shape)}'

    # --- Layer information & edges -----------------------------------------------
    layer_info = _get_layer_info(model)
    layer_map = {li['name']: li for li in layer_info}
    edges = _get_model_edges(model)

    # Detect smooth pairs to collapse (X -> X_smooth) into single display nodes.
    smooth_pair_sources = (
        _detect_smooth_pairs() if collapse_smooth_pairs else {}
    )
    skip_layer_names = set(smooth_pair_sources.values())
    smooth_names = set(smooth_pair_sources.keys())
    # Reverse map: source_name -> merged smooth_name.  Lets us redirect
    # A -> X into A -> X_smooth by looking up the smooth twin of X.
    smooth_pair_targets = {v: k for k, v in smooth_pair_sources.items()}

    # Rewrite edges: drop X -> X_smooth internal edges and redirect
    # A -> X to A -> X_smooth so the merged node receives all upstream wiring.
    # (X -> X_smooth is the only outgoing edge of a pair source, so by
    # dropping it we never leave a dangling X -> B edge.)
    if smooth_pair_sources:
        rewritten_edges = []
        for src, dst in edges:
            # Drop the internal X -> X_smooth edge entirely.
            if dst in smooth_names and src == smooth_pair_sources[dst]:
                continue
            # Redirect A -> X into A -> X_smooth.
            if dst in smooth_pair_targets:
                rewritten_edges.append((src, smooth_pair_targets[dst]))
            else:
                rewritten_edges.append((src, dst))
        edges = rewritten_edges

    refin_value_labels: List[str] = []
    if show_refin_values and 'ReferencesInput' in layer_map:
        refin_units = max(1, int(layer_map['ReferencesInput']['units']))
        resolved_refin = np.zeros(refin_units, dtype=np.float64)

        resolved_source = refin_values
        if resolved_source is None:
            for attr_name in ('reference_values', 'refin_values', 'references', 'reference_input_values'):
                if hasattr(individual, attr_name):
                    resolved_source = getattr(individual, attr_name)
                    break

        if resolved_source is not None:
            provided = np.asarray(resolved_source, dtype=np.float64).reshape(-1)
            n = min(refin_units, provided.shape[0])
            resolved_refin[:n] = provided[:n]
        refin_value_labels = [f"{v:.2f}" for v in resolved_refin]

    # --- Determine number of PCT levels from layer names -------------------------
    max_level = -1
    for li in layer_info:
        m = re.match(r'^(?:PL|RL|CL|OL)(\d+)', li['name'])
        if m:
            max_level = max(max_level, int(m.group(1)))

    # --- Assign each layer to a grid cell (row, col) -----------------------------
    # Columns: PL/CL/RL for level L -> odd col 2L+3  (starting at 3)
    #          OL  for level L       -> even col 2L+2 (starting at 2)
    # Rows:    1 = Observations + perception, 2 = comparator + output,
    #          3 = reference, 4 = actions, 5 = ReferencesInput + errors.
    highest_pl_col = 2 * max_level + 3 if max_level >= 0 else 3
    actions_col = highest_pl_col + 1
    grid_assignments: Dict[str, Tuple[int, int]] = {}
    for li in layer_info:
        name = li['name']
        base = re.match(r'^(PL|RL|CL|OL)(\d+)', name)
        if name == 'Observations':
            grid_assignments[name] = (1, 1)
        elif name == 'ReferencesInput':
            grid_assignments[name] = (5, 1)
        elif base:
            func, level = base.group(1), int(base.group(2))
            if func == 'PL':
                grid_assignments[name] = (1, 2 * level + 3)
            elif func == 'CL':
                grid_assignments[name] = (2, 2 * level + 3)
            elif func == 'OL':
                grid_assignments[name] = (2, 2 * level + 2)
            elif func == 'RL':
                grid_assignments[name] = (3, 2 * level + 3)
        elif name.startswith('Actions'):
            grid_assignments[name] = (4, actions_col)
        elif name == 'Errors':
            grid_assignments[name] = (5, actions_col)
        # Unrecognised layers are omitted from the diagram

    # --- Stack layers sharing a grid cell; optionally expand each layer by units --
    grid_cells: Dict[Tuple[int, int], List[str]] = {}
    for name, cell in grid_assignments.items():
        grid_cells.setdefault(cell, []).append(name)

    layer_spacing = circle_size * 3.0
    unit_spacing = circle_size * 1.8
    inter_row_clearance = circle_size * 1.6

    # When unit expansion is enabled, compute adaptive row spacing to avoid
    # vertical overlap between large unit stacks in adjacent rows.
    row_base_y: Dict[int, float] = {}
    if expand_units:
        cell_extents: Dict[Tuple[int, int], Tuple[float, float]] = {}
        for (row, col), names in grid_cells.items():
            n_layers = len(names)
            max_up = 0.0
            max_down = 0.0
            for i, name in enumerate(names):
                layer_off = (i - (n_layers - 1) / 2.0) * layer_spacing if n_layers > 1 else 0.0
                units = max(1, int(layer_map[name]['units']))
                unit_half = circle_size + ((units - 1) / 2.0) * unit_spacing if units > 1 else circle_size
                max_up = max(max_up, layer_off + unit_half)
                max_down = max(max_down, unit_half - layer_off)
            cell_extents[(row, col)] = (max_up, max_down)

        row_base_y[1] = -height_scale
        for row in range(2, 6):
            prev = row - 1
            required_gap = height_scale
            cols = {c for (r, c) in cell_extents if r in (prev, row)}
            for col in cols:
                if (prev, col) not in cell_extents or (row, col) not in cell_extents:
                    continue
                prev_down = cell_extents[(prev, col)][1]
                row_up = cell_extents[(row, col)][0]
                required_gap = max(required_gap, prev_down + row_up + inter_row_clearance)
            row_base_y[row] = row_base_y[prev] - required_gap
    else:
        row_base_y = {row: -row * height_scale for row in range(1, 6)}

    positions: Dict[Any, Tuple[float, float]] = {}
    layer_node_keys: Dict[str, List[Any]] = {}
    layer_centers: Dict[str, Tuple[float, float]] = {}

    for (row, col), names in grid_cells.items():
        x = col * width_scale
        base_y = row_base_y.get(row, -row * height_scale)
        n_layers = len(names)
        for i, name in enumerate(names):
            y_off = (i - (n_layers - 1) / 2.0) * layer_spacing if n_layers > 1 else 0.0
            center_y = base_y - y_off
            layer_centers[name] = (x, center_y)

            if expand_units:
                units = max(1, int(layer_map[name]['units']))
                keys: List[Any] = []
                for u in range(units):
                    unit_off = (u - (units - 1) / 2.0) * unit_spacing if units > 1 else 0.0
                    key = (name, u)
                    positions[key] = (x, center_y - unit_off)
                    keys.append(key)
                layer_node_keys[name] = keys
            else:
                positions[name] = (x, center_y)
                layer_node_keys[name] = [name]

    # --- Figure dimensions --------------------------------------------------------
    all_x = [p[0] for p in positions.values()]
    all_y = [p[1] for p in positions.values()]
    margin = max(1.5, circle_size * 5)
    x_min, x_max = min(all_x) - margin, max(all_x) + margin
    y_min, y_max = min(all_y) - margin, max(all_y) + margin

    fig_width = max(10, (x_max - x_min) * 1.0)
    fig_height = max(5, (y_max - y_min) * 1.5)

    fig, ax = plt.subplots(figsize=(fig_width, fig_height))
    ax.set_xlim(x_min, x_max)
    ax.set_ylim(y_min, y_max)
    ax.set_aspect('equal')
    ax.axis('off')
    ax.set_title(title, fontsize=16, fontweight='bold', pad=20)

    # --- Draw nodes ---------------------------------------------------------------
    node_patches: Dict[Any, patches.Circle] = {}
    if expand_units:
        for name, keys in layer_node_keys.items():
            if name in skip_layer_names:
                continue
            li = layer_map[name]
            ys = []
            smooth_factors = (
                _get_smooth_factors(name, li['units']) if show_smooth_factors else None
            )
            smooth_fs = smooth_factor_fontsize if smooth_factor_fontsize is not None else max(4, min(6, int(8 * circle_size)))
            for key in keys:
                x, y = positions[key]
                ys.append(y)
                circ = patches.Circle(
                    (x, y), circle_size,
                    facecolor=li['color'], edgecolor='black', linewidth=1.2, zorder=3,
                )
                ax.add_patch(circ)
                node_patches[key] = circ

                label = _unit_label(name, key[1])
                if label is None and name == 'ReferencesInput' and refin_value_labels:
                    if key[1] < len(refin_value_labels):
                        label = refin_value_labels[key[1]]
                if show_unit_labels and label:
                    ax.text(
                        x, y, label,
                        ha='center', va='center',
                        fontsize=circle_label_fontsize if circle_label_fontsize is not None else max(4, min(7, int(14 * circle_size))),
                        color='black', zorder=4,
                    )

                # Annotate this unit's smooth_factor just below the circle.
                if smooth_factors is not None and key[1] < len(smooth_factors):
                    ax.text(
                        x, y - circle_size - 0.05,
                        f"α={smooth_factors[key[1]]:.{smooth_factor_decimals}f}",
                        ha='center', va='top', fontsize=smooth_fs,
                        color='#777777', zorder=4,
                    )

            x_center, _ = layer_centers[name]
            y_top = max(ys)
            y_bottom = min(ys)
            display_name = {
                'Observations': 'Obs.',
                'ReferencesInput': 'RefIn.',
            }.get(name, name)
            title_x = x_center
            title_y = y_top + circle_size + 0.35
            if name.startswith('Actions') or name == 'Errors':
                title_x = x_center + circle_size * 1.8
                title_y = y_top + circle_size + 0.1
            ax.text(
                title_x, title_y, display_name,
                ha='center', va='bottom', fontsize=8, fontweight='bold', zorder=4,
            )
            bottom_label = f"({li['type']}, {li['units']})"
            ax.text(
                x_center, y_bottom - circle_size - 0.15,
                bottom_label,
                ha='center', va='top', fontsize=bottom_label_fontsize, color='#555555'
            )
    else:
        for name, (x, y) in positions.items():
            if name in skip_layer_names:
                continue
            li = layer_map[name]
            circ = patches.Circle(
                (x, y), circle_size,
                facecolor=li['color'], edgecolor='black', linewidth=1.5, zorder=3,
            )
            ax.add_patch(circ)
            node_patches[name] = circ

            display_name = {
                'Observations': 'Obs.',
                'ReferencesInput': 'RefIn.',
            }.get(name, name)
            fs = circle_label_fontsize if circle_label_fontsize is not None else max(6, min(10, int(80 / max(len(display_name), 1))))
            ax.text(
                x, y, display_name, ha='center', va='center',
                fontsize=fs, fontweight='bold', zorder=4
            )
            bottom_label = f"({li['type']}, {li['units']})"
            if show_smooth_factors:
                smooth_text = _smooth_label(name, li['units'])
                if smooth_text is not None:
                    bottom_label = f"{bottom_label}, {smooth_text}"
            # When the smooth node absorbed a paired source (Dense/EWML), show
            # the underlying weights so the merged display still exposes them.
            source_name = smooth_pair_sources.get(name)
            if source_name is not None:
                kernel_text = _get_kernel_summary(source_name)
                if kernel_text is not None:
                    bottom_label = f"{bottom_label}, {kernel_text}"
            ax.text(
                x, y - circle_size - 0.15, bottom_label,
                ha='center', va='top', fontsize=bottom_label_fontsize, color='#555555'
            )

    # --- Draw edges ----------------------------------------------------------------
    for src, dst in edges:
        if src not in layer_node_keys or dst not in layer_node_keys:
            continue

        src_pct = layer_map.get(src, {}).get('pct_type', '')
        dst_pct = layer_map.get(dst, {}).get('pct_type', '')
        if src_pct == 'errors' or dst_pct == 'errors':
            continue

        if src_pct == 'output' and dst_pct == 'actions':
            conn_style = 'angle,angleA=-90,angleB=0'
        elif src == 'ReferencesInput' and dst_pct == 'reference':
            conn_style = 'angle,angleA=0,angleB=90'
        else:
            conn_style = 'arc3,rad=0.0'

        if expand_units:
            edge_pairs = _unit_edge_pairs(src, dst)
            for src_key, dst_key in edge_pairs:
                arrow = patches.FancyArrowPatch(
                    posA=positions[src_key],
                    posB=positions[dst_key],
                    arrowstyle='->,head_length=8,head_width=4',
                    connectionstyle=conn_style,
                    color='gray',
                    alpha=0.5,
                    linewidth=max(0.75, line_thickness * 0.825),
                    zorder=1,
                    patchA=node_patches[src_key],
                    patchB=node_patches[dst_key],
                    shrinkA=2,
                    shrinkB=2,
                )
                ax.add_patch(arrow)
                if show_weights:
                    wv = _get_connection_weight(dst, src_key[1], dst_key[1])
                    if wv is not None:
                        mx = (positions[src_key][0] + positions[dst_key][0]) / 2
                        my = (positions[src_key][1] + positions[dst_key][1]) / 2
                        wfs = weight_fontsize if weight_fontsize is not None else max(4, min(6, int(10 * circle_size)))
                        ax.text(mx, my, f'{wv:.2f}', ha='center', va='center',
                                fontsize=wfs, color='#333333', zorder=5)
        else:
            src_key = layer_node_keys[src][len(layer_node_keys[src]) // 2]
            dst_key = layer_node_keys[dst][len(layer_node_keys[dst]) // 2]

            arrow_kwargs = dict(
                posA=positions[src_key],
                posB=positions[dst_key],
                arrowstyle='->,head_length=6,head_width=3',
                connectionstyle=conn_style,
                color='gray',
                alpha=0.6,
                linewidth=line_thickness,
                zorder=2,
            )
            arrow_kwargs['patchA'] = node_patches[src_key]
            arrow_kwargs['patchB'] = node_patches[dst_key]

            arrow = patches.FancyArrowPatch(**arrow_kwargs)
            ax.add_patch(arrow)

    # --- Legend ------------------------------------------------------------------
    if show_legend:
        seen: Dict[str, str] = {}
        for li in layer_info:
            if li['name'] not in layer_node_keys:
                continue
            pt = li['pct_type']
            if pt not in seen:
                seen[pt] = li['color']
        handles = [
            patches.Patch(facecolor=c, edgecolor='black', label=t.capitalize())
            for t, c in seen.items()
        ]
        ax.legend(
            handles=handles,
            loc='upper right',
            fontsize=legend_fontsize,
            title='PCT Layer Type',
            title_fontsize=legend_title_fontsize,
        )

    plt.tight_layout(pad=2.0)
    if filename is not None:
        plt.savefig(filename, dpi=dpi, bbox_inches='tight', facecolor='white')
    return fig


# %% ../nbs/03_visualization.ipynb #042dcf88
def draw_traditional_pcnn(
    individual,                         # DHPCTIndividual (must be compiled) or a Keras Model
    filename: Optional[str] = None,     # output image path (None = don't save)
    title: str = 'DHPCTIndividual',     # figure title
    width_scale: float = 2.5,           # horizontal spacing between grid columns
    height_scale: float = 2.0,          # vertical spacing between grid rows
    circle_size: float = 0.5,           # node circle radius
    line_thickness: float = 5.0,        # connection line width
    show_legend: bool = True,           # display colour legend
    expand_units: bool = False,         # draw one circle per unit when True
    dpi: int = 150,                     # output resolution
    circle_label_fontsize: Optional[int] = 16,  # circle label font size (None = auto)
    show_weights: bool = False,         # show weight values on connections (expand_units only)
    weight_fontsize: Optional[int] = 14,  # weight label font size (None = auto)
    bottom_label_fontsize: int = 14,     # bottom metadata label font size
    legend_fontsize: int = 16,           # legend label font size
    legend_title_fontsize: int = 15,    # legend title font size
    show_unit_labels: bool = True,      # show unit labels inside expanded nodes
    show_refin_values: bool = True,     # show ReferencesInput node values
    refin_values: Optional[List[float]] = None,  # optional explicit ReferencesInput values
    show_smooth_factors: bool = True,   # show alpha (smooth_factor) on ExponentialSmoothLayer nodes
    smooth_factor_decimals: int = 2,    # number of decimals to display for smooth_factor
    smooth_factor_fontsize: Optional[int] = 12,  # font size for smooth_factor labels (None = auto)
    collapse_smooth_pairs: bool = True, # merge Dense/EWML + ExponentialSmoothLayer pairs into one node
):
    """Draw a DHPCTIndividual's compiled Keras model on a vertical grid.

    The layout flows bottom-to-top for perception layers and top-to-bottom
    for reference layers, arranged on a 3-column grid:

    * **Col 1** (left)   - Perception layers (PL), Observations
    * **Col 2** (centre) - Comparator (CL), Output (OL), Actions
    * **Col 3** (right)  - Reference layers (RL), ReferencesInput, Errors

    Rows are arranged so the highest PCT level is at the top:

    * **Row 1**          - ReferencesInput
    * **Rows 2..4**      - PL/RL, CL, OL for highest level (top-down)
    * ...                - repeated for each level down to 0
    * **Last row**       - Observations, Actions, Errors

    When ``top_level_obs_indices`` is used, an additional row is inserted
    between the top-level perception layer and Observations for the
    ``GatherObs##`` / ``GatherObsL##`` Lambda layer, and connections to/from it are drawn
    as single one-to-one links.

    Parameters
    ----------
    individual : DHPCTIndividual or keras.Model
        A compiled individual (uses ``individual.model``) or a raw Keras model.
    filename : str or None
        File path for the saved image.  If *None* the figure is returned
        without saving.
    title : str
        Title displayed above the diagram.
    width_scale : float
        Horizontal spacing multiplier between grid columns.
    height_scale : float
        Vertical spacing multiplier between grid rows.
    circle_size : float
        Radius of each node circle.
    line_thickness : float
        Width of connection lines.
    show_legend : bool
        If True, add a colour legend for PCT layer types.
    expand_units : bool
        If False (default), draw one circle per layer.
        If True, draw one circle per output unit in each layer.
    dpi : int
        Resolution of the saved image.
    circle_label_fontsize : int or None
        Font size for circle labels. If None, auto-calculated from circle_size.
    show_weights : bool
        If True and *expand_units* is True, display the weight value on
        each unit-to-unit connection.
    weight_fontsize : int or None
        Font size for weight labels. If None, auto-calculated from
        *circle_size*.
    bottom_label_fontsize : int
        Font size for per-node bottom metadata labels such as
        ``(Dense, 1)``.
    legend_fontsize : int
        Font size for legend entries.
    legend_title_fontsize : int
        Font size for the legend title.
    show_unit_labels : bool
        If True (default), render per-unit labels in expanded diagrams.
    show_refin_values : bool
        If True (default), annotate expanded ``ReferencesInput`` unit nodes
        with numeric values.
    refin_values : list[float] or None
        Optional values for ``ReferencesInput`` units. If None, values
        default to zeros of matching size.
    show_smooth_factors : bool
        If True (default), annotate ``ExponentialSmoothLayer`` nodes with
        their ``smooth_factor`` (α) values.  In ``expand_units`` mode each
        unit's α is rendered as a small text below its circle; in collapsed
        mode the α is appended to the layer's bottom ``(type, units)`` label.
    smooth_factor_decimals : int
        Number of decimal places used when rendering α values (default 2).
    smooth_factor_fontsize : int or None
        Font size for the per-unit α annotations when ``expand_units`` is
        True.  If None, auto-calculated from *circle_size*.
    collapse_smooth_pairs : bool
        If True (default), each ``X`` (Dense / ElementWiseMultiplyLayer)
        immediately followed by ``X_smooth`` (ExponentialSmoothLayer) is
        rendered as a single node.  The merged node keeps the ``X_smooth``
        display name (so the ``_smooth`` suffix is preserved), shows the
        underlying ``X`` weights, and shows the ``X_smooth`` α on its
        existing label.  Set False to keep the original two-node behaviour
        (one circle for ``X`` and one for ``X_smooth``).

    Returns
    -------
    fig : matplotlib.figure.Figure
        The matplotlib figure object.  The figure is **not** displayed
        automatically; call ``display(fig)`` to render it in a notebook.
    """
    model = getattr(individual, 'model', individual)
    if model is None:
        raise ValueError(
            "Individual is not compiled.  Call individual.compile() first."
        )

    def _unit_label(layer_name: str, unit_idx: int) -> Optional[str]:
        """Return per-unit labels like P00C00, C00C01, etc."""
        m = re.match(r'^(PL|CL|RL|OL)(\d+)', layer_name)
        if not m:
            return None
        prefix = {'PL': 'P', 'CL': 'C', 'RL': 'R', 'OL': 'O'}[m.group(1)]
        return f"{prefix}{int(m.group(2)):02d}C{unit_idx:02d}"

    def _unit_edge_pairs(src_name: str, dst_name: str) -> List[Tuple[Any, Any]]:
        """Return concrete unit-to-unit edge pairs for one layer-level edge."""
        src_keys = layer_node_keys[src_name]
        dst_keys = layer_node_keys[dst_name]
        src_units = len(src_keys)
        dst_units = len(dst_keys)

        # Special handling for obs_gather layers: each gather unit reads
        # from exactly one observation at the index given by the
        # corresponding individual attribute.  Zero-level gathers use
        # ``zerolevel_inputs_indexes``; top-level gathers use
        # ``top_level_obs_indices``.
        if dst_name.startswith('GatherObs'):
            if dst_name.startswith('GatherObsL'):
                obs_indices = getattr(individual, 'level0_observation_indices', None)
                if obs_indices is None:
                    obs_indices = getattr(individual, 'zerolevel_inputs_indexes', None)
            else:
                obs_indices = getattr(individual, 'top_level_obs_indices', None)
            if obs_indices is not None and len(obs_indices) == dst_units:
                return [
                    (src_keys[idx], dst_keys[i])
                    for i, idx in enumerate(obs_indices)
                    if idx < src_units
                ]

        # obs_gather → PL (ElementWiseMultiplyLayer): one-to-one
        if src_name.startswith('GatherObs'):
            if src_units == dst_units:
                return [(src_keys[i], dst_keys[i]) for i in range(src_units)]

        dst_type = layer_map.get(dst_name, {}).get('type', '')
        # When a Dense/EWML -> smooth pair is collapsed, incoming A -> Dense
        # edges are rewritten as A -> smooth.  Route those incoming edges using
        # the absorbed source layer's semantics, not the smooth layer's
        # one-to-one semantics.  Otherwise dense perception inputs such as
        # Observations -> PL00_smooth are drawn as Obs0->P00C00 and
        # Obs1->P00C01 instead of all observations feeding every P00 unit.
        absorbed_source = smooth_pair_sources.get(dst_name)
        if absorbed_source is not None and src_name != absorbed_source:
            dst_type = layer_map.get(absorbed_source, {}).get('type', dst_type)

        one_to_one_ops = {'Subtract', 'ElementWiseMultiplyLayer', 'Multiply', 'Add',
                          'ExponentialSmoothLayer'}

        if dst_type in one_to_one_ops and src_units == dst_units:
            return [(src_keys[i], dst_keys[i]) for i in range(src_units)]
        if src_units == 1:
            return [(src_keys[0], dk) for dk in dst_keys]
        if dst_units == 1:
            return [(sk, dst_keys[0]) for sk in src_keys]
        return [(sk, dk) for sk in src_keys for dk in dst_keys]

    def _get_connection_weight(dst_name, src_unit, dst_unit):
        """Return the weight value for a unit-to-unit connection, or None.

        When the destination is a smooth layer that absorbed a paired
        Dense / ElementWiseMultiplyLayer source (``smooth_pair_sources``
        maps smooth_name → source_name), the weight lookup falls through
        to the source's kernel so the merged node still exposes its
        incoming edge weights.
        """
        try:
            dst_layer = model.get_layer(dst_name)
        except ValueError:
            return None
        w = dst_layer.get_weights()
        layer_type = type(dst_layer).__name__
        # If this smooth layer absorbed a weighted source, defer to that
        # source's kernel for the weight annotation.
        source_name = smooth_pair_sources.get(dst_name)
        if source_name is not None and (not w or layer_type == 'ExponentialSmoothLayer'):
            try:
                src_layer = model.get_layer(source_name)
            except ValueError:
                return None
            w = src_layer.get_weights()
            if not w:
                return None
            layer_type = type(src_layer).__name__
        else:
            if not w:
                return None
        if layer_type == 'Dense':
            kernel = w[0]
            if src_unit < kernel.shape[0] and dst_unit < kernel.shape[1]:
                return float(kernel[src_unit, dst_unit])
        elif layer_type == 'ElementWiseMultiplyLayer':
            ow = w[0]
            if dst_unit < ow.shape[0]:
                return float(ow[dst_unit])
        return None

    def _get_smooth_factors(layer_name: str, units: int) -> Optional[List[float]]:
        """Return per-unit ``smooth_factor`` values for an ExponentialSmoothLayer.

        Returns ``None`` if the layer is not an ``ExponentialSmoothLayer`` or
        has no weights.  Scalar smooth_factors are broadcast to a list of the
        requested length.
        """
        try:
            layer = model.get_layer(layer_name)
        except ValueError:
            return None
        if type(layer).__name__ != 'ExponentialSmoothLayer':
            return None
        w = layer.get_weights()
        if not w:
            return None
        sf = np.asarray(w[0]).reshape(-1)
        if sf.shape[0] == 1:
            return [float(sf[0])] * max(1, units)
        return [float(v) for v in sf[:max(1, units)]]

    def _smooth_label(name: str, layer_units: int) -> Optional[str]:
        """Build the smooth-factor annotation text for a non-expanded layer."""
        sfs = _get_smooth_factors(name, layer_units)
        if sfs is None:
            return None
        if len(sfs) == 1 or all(abs(sfs[0] - s) < 1e-9 for s in sfs):
            return f"α={sfs[0]:.{smooth_factor_decimals}f}"
        return "α=[" + ",".join(f"{v:.{smooth_factor_decimals}f}" for v in sfs) + "]"

    def _detect_smooth_pairs():
        """Detect ``X`` -> ``X_smooth`` pairs to collapse when ``collapse_smooth_pairs=True``.

        Returns a mapping ``{smooth_name: source_name}``.  The source must
        exist in the model, must be a ``Dense`` or
        ``ElementWiseMultiplyLayer`` layer, and its only consumer must be the
        paired ``ExponentialSmoothLayer``.  Pairs whose source is also a
        ``_smooth`` or ``_sigmoid`` suffix layer are skipped (nested
        activations are not yet supported).
        """
        pairs = {}
        # First pass: identify the immediate consumer of each layer.
        consumer_of = {li['name']: [] for li in layer_info}
        for src, dst in edges:
            if src in consumer_of:
                consumer_of[src].append(dst)

        smooth_types = {'ExponentialSmoothLayer'}
        mergeable_source_types = {'Dense', 'ElementWiseMultiplyLayer'}
        for li in layer_info:
            name = li['name']
            li_type = li['type']
            if li_type not in smooth_types:
                continue
            if not name.endswith('_smooth'):
                continue
            source_name = name[:-len('_smooth')]
            if source_name not in layer_map:
                continue
            if layer_map[source_name]['type'] not in mergeable_source_types:
                continue
            consumers = consumer_of.get(source_name, [])
            if consumers != [name]:
                # Only collapse when the source is dedicated to this smooth layer.
                continue
            pairs[name] = source_name
        return pairs

    def _get_kernel_summary(layer_name):
        """Return a compact text summary of a Dense/EWML kernel for display."""
        try:
            layer = model.get_layer(layer_name)
        except ValueError:
            return None
        w = layer.get_weights()
        if not w:
            return None
        kernel = np.asarray(w[0])
        flat = kernel.reshape(-1)
        if flat.size <= 4:
            vals = ', '.join(f'{v:.2f}' for v in flat)
            return f'w=[{vals}]'
        if kernel.ndim == 1:
            head = ', '.join(f'{v:.2f}' for v in flat[:4])
            return f'w=[{head}, ...]'
        return f'W{tuple(kernel.shape)}'

    # --- Layer information & edges -----------------------------------------------
    layer_info = _get_layer_info(model)
    layer_map = {li['name']: li for li in layer_info}
    edges = _get_model_edges(model)

    # Detect smooth pairs to collapse (X -> X_smooth) into single display nodes.
    smooth_pair_sources = (
        _detect_smooth_pairs() if collapse_smooth_pairs else {}
    )
    skip_layer_names = set(smooth_pair_sources.values())
    smooth_names = set(smooth_pair_sources.keys())
    # Reverse map: source_name -> merged smooth_name.  Lets us redirect
    # A -> X into A -> X_smooth by looking up the smooth twin of X.
    smooth_pair_targets = {v: k for k, v in smooth_pair_sources.items()}

    # Rewrite edges: drop X -> X_smooth internal edges and redirect
    # A -> X to A -> X_smooth so the merged node receives all upstream wiring.
    # (X -> X_smooth is the only outgoing edge of a pair source, so by
    # dropping it we never leave a dangling X -> B edge.)
    if smooth_pair_sources:
        rewritten_edges = []
        for src, dst in edges:
            # Drop the internal X -> X_smooth edge entirely.
            if dst in smooth_names and src == smooth_pair_sources[dst]:
                continue
            # Redirect A -> X into A -> X_smooth.
            if dst in smooth_pair_targets:
                rewritten_edges.append((src, smooth_pair_targets[dst]))
            else:
                rewritten_edges.append((src, dst))
        edges = rewritten_edges

    refin_value_labels: List[str] = []
    if show_refin_values and 'ReferencesInput' in layer_map:
        refin_units = max(1, int(layer_map['ReferencesInput']['units']))
        resolved_refin = np.zeros(refin_units, dtype=np.float64)

        resolved_source = refin_values
        if resolved_source is None:
            for attr_name in ('reference_values', 'refin_values', 'references', 'reference_input_values'):
                if hasattr(individual, attr_name):
                    resolved_source = getattr(individual, attr_name)
                    break

        if resolved_source is not None:
            provided = np.asarray(resolved_source, dtype=np.float64).reshape(-1)
            n = min(refin_units, provided.shape[0])
            resolved_refin[:n] = provided[:n]
        refin_value_labels = [f"{v:.2f}" for v in resolved_refin]

    error_level_unit_labels: List[str] = []
    if expand_units and 'Errors' in layer_map:
        cl_level_pattern = r'^CL(\d+)'
        cl_sort_fallback_level = 10 ** 9  # Keep non-matching names sorted last.

        def _cl_level_key(layer_item: Dict[str, Any]) -> int:
            m = re.match(cl_level_pattern, layer_item['name'])
            return int(m.group(1)) if m else cl_sort_fallback_level

        cl_layers = sorted(
            (li for li in layer_info if re.match(cl_level_pattern, li['name'])),
            key=_cl_level_key,
        )
        for li in cl_layers:
            units = max(1, int(li['units']))
            for unit_idx in range(units):
                label = _unit_label(li['name'], unit_idx)
                if label:
                    error_level_unit_labels.append(label)

        if not error_level_unit_labels:
            # Fallback for models where Errors exists but explicit comparator
            # layers are unavailable in the rendered layer list.
            error_units = max(1, int(layer_map['Errors']['units']))
            error_level_unit_labels = [f"L{i:02d}" for i in range(error_units)]

    # --- Determine number of PCT levels from layer names -------------------------
    max_level = -1
    for li in layer_info:
        m = re.match(r'^(?:PL|RL|CL|OL)(\d+)', li['name'])
        if m:
            max_level = max(max_level, int(m.group(1)))

    # --- Assign each layer to a grid cell (row, col) -----------------------------
    # Vertical layout: 3 columns, rows top-to-bottom.
    # Row 1: ReferencesInput (col 3)
    # For each level L from max_level down to 0:
    #   row_base = 1 + (max_level - L) * 3 + 1
    #   PL{L} -> (row_base, 1),  RL{L} -> (row_base, 3)
    #   CL{L} -> (row_base+1, 2)
    #   OL{L} -> (row_base+2, 2)
    # Bottom row: Obs (1), Actions (2), Errors (3)
    bottom_row = 1 + (max_level + 1) * 3 + 1 if max_level >= 0 else 5

    # Detect obs_gather layers and insert an extra row between PL and Observations
    obs_gather_names = [
        li['name'] for li in layer_info
        if re.match(r'^GatherObsL?\d+$', li['name'])
    ]
    obs_gather_row = None
    if obs_gather_names:
        obs_gather_row = bottom_row
        bottom_row += 1

    grid_assignments: Dict[str, Tuple[int, int]] = {}
    for li in layer_info:
        name = li['name']
        if name == 'Observations':
            # Place Observations at column 0 so the horizontal GatherObs->PL
            # connection lines have clear visual space and are not obscured
            # by PL00 units sitting directly on top of the gather layer.
            grid_assignments[name] = (bottom_row, 0)
        elif name == 'ReferencesInput':
            grid_assignments[name] = (1, 3)
        elif re.match(r'^GatherObsL?(\d+)$', name):
            # Place each obs_gather on its own row between PL and Observations,
            # so multiple gathers (one per level / one per obs_index) sit side-by-side
            # along the x-axis rather than stacking on the same grid cell.
            gather_lvl = int(re.match(r'^GatherObsL?(\d+)$', name).group(1))
            grid_assignments[name] = (obs_gather_row, 1 + 2 * gather_lvl)
        elif re.match(r'^(PL|RL|CL|OL)(\d+)', name):
            base = re.match(r'^(PL|RL|CL|OL)(\d+)', name)
            func, level = base.group(1), int(base.group(2))
            row_base = 1 + (max_level - level) * 3 + 1
            if func == 'PL':
                grid_assignments[name] = (row_base, 1)
            elif func == 'RL':
                grid_assignments[name] = (row_base, 3)
            elif func == 'CL':
                grid_assignments[name] = (row_base + 1, 2)
            elif func == 'OL':
                grid_assignments[name] = (row_base + 2, 2)
        elif name.startswith('Actions'):
            grid_assignments[name] = (bottom_row, 2)
        elif name == 'Errors':
            grid_assignments[name] = (bottom_row, 3)

    # --- Stack layers sharing a grid cell; optionally expand by units ------------
    grid_cells: Dict[Tuple[int, int], List[str]] = {}
    for name, cell in grid_assignments.items():
        grid_cells.setdefault(cell, []).append(name)

    layer_spacing = circle_size * 3.0
    unit_spacing = circle_size * 1.8
    inter_row_clearance = circle_size * 1.6

    # Adaptive row spacing when units are expanded
    row_base_y: Dict[int, float] = {}
    max_row = max(r for r, c in grid_cells) if grid_cells else 1
    if expand_units:
        cell_extents: Dict[Tuple[int, int], Tuple[float, float]] = {}
        for (row, col), names in grid_cells.items():
            n_layers = len(names)
            max_up = 0.0
            max_down = 0.0
            for i, name in enumerate(names):
                layer_off = (i - (n_layers - 1) / 2.0) * layer_spacing if n_layers > 1 else 0.0
                # Units arranged horizontally, so vertical extent is just circle_size
                max_up = max(max_up, layer_off + circle_size)
                max_down = max(max_down, circle_size - layer_off)
            cell_extents[(row, col)] = (max_up, max_down)

        row_base_y[1] = -height_scale
        for row in range(2, max_row + 1):
            prev = row - 1
            required_gap = height_scale
            cols = {c for (r, c) in cell_extents if r in (prev, row)}
            for col in cols:
                if (prev, col) not in cell_extents or (row, col) not in cell_extents:
                    continue
                prev_down = cell_extents[(prev, col)][1]
                row_up = cell_extents[(row, col)][0]
                required_gap = max(required_gap, prev_down + row_up + inter_row_clearance)
            row_base_y[row] = row_base_y[prev] - required_gap
    else:
        row_base_y = {row: -row * height_scale for row in range(1, max_row + 1)}

    positions: Dict[Any, Tuple[float, float]] = {}
    layer_node_keys: Dict[str, List[Any]] = {}
    layer_centers: Dict[str, Tuple[float, float]] = {}

    for (row, col), names in grid_cells.items():
        x = col * width_scale
        base_y = row_base_y.get(row, -row * height_scale)
        n_layers = len(names)
        for i, name in enumerate(names):
            y_off = (i - (n_layers - 1) / 2.0) * layer_spacing if n_layers > 1 else 0.0
            center_y = base_y - y_off
            layer_centers[name] = (x, center_y)

            if expand_units:
                units = 1 if name == 'Errors' else max(1, int(layer_map[name]['units']))
                keys: List[Any] = []
                for u in range(units):
                    unit_off = (u - (units - 1) / 2.0) * unit_spacing if units > 1 else 0.0
                    key = (name, u)
                    positions[key] = (x + unit_off, center_y)
                    keys.append(key)
                layer_node_keys[name] = keys
            else:
                positions[name] = (x, center_y)
                layer_node_keys[name] = [name]

    # Re-position GatherObs units horizontally to align with their source
    # Observations unit. Each GatherObs unit i selects observation index
    # obs_indices[i], so its x-coordinate should match Observations[obs_indices[i]]
    # for a clean vertical Obs -> Gather edge.
    obs_pos_by_unit = {}
    if 'Observations' in layer_node_keys:
        for u, key in enumerate(layer_node_keys['Observations']):
            obs_pos_by_unit[u] = positions[key][0]

    if expand_units and obs_pos_by_unit:
        # Re-position each GatherObs unit horizontally to align with its source
        # Observations unit. Each gather layer is placed in its own grid cell
        # (column), so no y-stacking offset is needed.
        gather_layers = [n for n in layer_node_keys if re.match(r'^GatherObs(L?)\d+$', n)]
        for gname in gather_layers:
            # Determine source obs indices attribute by name pattern
            if gname.startswith('GatherObsL'):
                indices = getattr(individual, 'level0_observation_indices', None)
                if indices is None:
                    indices = getattr(individual, 'zerolevel_inputs_indexes', None)
            else:
                indices = getattr(individual, 'top_level_obs_indices', None)
            if indices is None:
                continue
            units = max(1, int(layer_map[gname]['units']))
            for u in range(units):
                key = (gname, u)
                if key not in positions:
                    continue
                _, cur_y = positions[key]
                if u < len(indices):
                    obs_idx = indices[u]
                    if obs_idx in obs_pos_by_unit:
                        new_x = obs_pos_by_unit[obs_idx]
                    else:
                        # Fallback: distribute uniformly if obs_idx out of range
                        new_x = obs_pos_by_unit.get(min(obs_idx, max(obs_pos_by_unit)), 0.0)
                else:
                    # No obs index for this unit: keep current x
                    new_x = positions[key][0]
                positions[key] = (new_x, cur_y)
                layer_centers[gname] = (new_x, cur_y)


    # --- Figure dimensions --------------------------------------------------------
    all_x = [p[0] for p in positions.values()]
    all_y = [p[1] for p in positions.values()]
    margin = max(1.5, circle_size * 5)
    x_min, x_max = min(all_x) - margin, max(all_x) + margin
    y_min, y_max = min(all_y) - margin, max(all_y) + margin

    fig_width = max(8, (x_max - x_min) * 1.2)
    fig_height = max(8, (y_max - y_min) * 1.2)

    fig, ax = plt.subplots(figsize=(fig_width, fig_height))
    ax.set_xlim(x_min, x_max)
    ax.set_ylim(y_min, y_max)
    ax.set_aspect('equal')
    ax.axis('off')
    ax.set_title(title, fontsize=16, fontweight='bold', pad=20)

    # --- Draw nodes ---------------------------------------------------------------
    node_patches: Dict[Any, patches.Circle] = {}
    if expand_units:
        for name, keys in layer_node_keys.items():
            if name in skip_layer_names:
                continue
            li = layer_map[name]
            ys = []
            smooth_factors = (
                _get_smooth_factors(name, li['units']) if show_smooth_factors else None
            )
            smooth_fs = smooth_factor_fontsize if smooth_factor_fontsize is not None else max(4, min(6, int(8 * circle_size)))
            for key in keys:
                x, y = positions[key]
                ys.append(y)
                circ = patches.Circle(
                    (x, y), circle_size,
                    facecolor=li['color'], edgecolor='black', linewidth=1.2, zorder=3,
                )
                ax.add_patch(circ)
                node_patches[key] = circ

                label = _unit_label(name, key[1])
                if label is None and name == 'ReferencesInput' and refin_value_labels:
                    if key[1] < len(refin_value_labels):
                        label = refin_value_labels[key[1]]
                if show_unit_labels and label:
                    ax.text(
                        x, y, label,
                        ha='center', va='center',
                        fontsize=circle_label_fontsize if circle_label_fontsize is not None else max(4, min(7, int(14 * circle_size))),
                        color='black', zorder=4,
                    )

                # Annotate this unit's smooth_factor just below the circle.
                if smooth_factors is not None and key[1] < len(smooth_factors):
                    ax.text(
                        x, y - circle_size - 0.05,
                        f"α={smooth_factors[key[1]]:.{smooth_factor_decimals}f}",
                        ha='center', va='top', fontsize=smooth_fs,
                        color='#777777', zorder=4,
                    )

            x_center, center_y = layer_centers[name]
            y_top = max(ys)
            y_bottom = min(ys)
            display_name = {
                'Observations': 'Obs.',
                'ReferencesInput': 'RefIn.',
            }.get(name, name)
            ax.text(
                x_center, y_top + circle_size + 0.35, display_name,
                ha='center', va='bottom',
                fontsize=(circle_label_fontsize if circle_label_fontsize is not None else 8),
                fontweight='bold', zorder=4,
            )

            if name == 'Errors' and error_level_unit_labels:
                error_label_min_fontsize = 5
                error_label_default_fontsize = 6
                error_label_fontsize = (
                    max(error_label_min_fontsize, circle_label_fontsize - 1)
                    if circle_label_fontsize is not None else error_label_default_fontsize
                )
                ax.text(
                    x_center + circle_size * 2.2,
                    center_y,
                    '\n'.join(error_level_unit_labels),
                    ha='left', va='center',
                    fontsize=error_label_fontsize,
                    color='black', zorder=4,
                )

            bottom_label = f"({li['type']}, {li['units']})"
            ax.text(
                x_center, y_bottom - circle_size - 0.15,
                bottom_label,
                ha='center', va='top', fontsize=bottom_label_fontsize, color='#555555'
            )
    else:
        for name, (x, y) in positions.items():
            if name in skip_layer_names:
                continue
            li = layer_map[name]
            circ = patches.Circle(
                (x, y), circle_size,
                facecolor=li['color'], edgecolor='black', linewidth=1.5, zorder=3,
            )
            ax.add_patch(circ)
            node_patches[name] = circ

            display_name = {
                'Observations': 'Obs.',
                'ReferencesInput': 'RefIn.',
            }.get(name, name)
            fs = circle_label_fontsize if circle_label_fontsize is not None else max(6, min(10, int(80 / max(len(display_name), 1))))
            ax.text(
                x, y, display_name, ha='center', va='center',
                fontsize=fs, fontweight='bold', zorder=4
            )
            bottom_label = f"({li['type']}, {li['units']})"
            if show_smooth_factors:
                smooth_text = _smooth_label(name, li['units'])
                if smooth_text is not None:
                    bottom_label = f"{bottom_label}, {smooth_text}"
            # When the smooth node absorbed a paired source (Dense/EWML), show
            # the underlying weights so the merged display still exposes them.
            source_name = smooth_pair_sources.get(name)
            if source_name is not None:
                kernel_text = _get_kernel_summary(source_name)
                if kernel_text is not None:
                    bottom_label = f"{bottom_label}, {kernel_text}"
            ax.text(
                x, y - circle_size - 0.15, bottom_label,
                ha='center', va='top', fontsize=bottom_label_fontsize, color='#555555'
            )

    # --- Draw edges ----------------------------------------------------------------
    for src, dst in edges:
        if src not in layer_node_keys or dst not in layer_node_keys:
            continue

        src_pct = layer_map.get(src, {}).get('pct_type', '')
        dst_pct = layer_map.get(dst, {}).get('pct_type', '')
        if src_pct == 'errors' or dst_pct == 'errors':
            continue

        # Choose connection style for the vertical layout
        if src == 'ReferencesInput' and dst_pct == 'reference':
            conn_style = 'angle,angleA=-90,angleB=0'
        elif src_pct == 'output' and dst_pct == 'actions':
            conn_style = 'arc3,rad=0.0'
        else:
            conn_style = 'arc3,rad=0.0'

        if expand_units:
            edge_pairs = _unit_edge_pairs(src, dst)
            for src_key, dst_key in edge_pairs:
                arrow = patches.FancyArrowPatch(
                    posA=positions[src_key],
                    posB=positions[dst_key],
                    arrowstyle='->,head_length=8,head_width=4',
                    connectionstyle=conn_style,
                    color='gray',
                    alpha=0.5,
                    linewidth=max(0.75, line_thickness * 0.825),
                    zorder=1,
                    patchA=node_patches[src_key],
                    patchB=node_patches[dst_key],
                    shrinkA=2,
                    shrinkB=2,
                )
                ax.add_patch(arrow)
                if show_weights:
                    wv = _get_connection_weight(dst, src_key[1], dst_key[1])
                    if wv is not None:
                        mx = (positions[src_key][0] + positions[dst_key][0]) / 2
                        my = (positions[src_key][1] + positions[dst_key][1]) / 2
                        wfs = weight_fontsize if weight_fontsize is not None else max(4, min(6, int(10 * circle_size)))
                        ax.text(mx, my, f'{wv:.2f}', ha='center', va='center',
                                fontsize=wfs, color='#333333', zorder=5)
        else:
            src_key = layer_node_keys[src][len(layer_node_keys[src]) // 2]
            dst_key = layer_node_keys[dst][len(layer_node_keys[dst]) // 2]

            arrow_kwargs = dict(
                posA=positions[src_key],
                posB=positions[dst_key],
                arrowstyle='->,head_length=6,head_width=3',
                connectionstyle=conn_style,
                color='gray',
                alpha=0.6,
                linewidth=line_thickness,
                zorder=2,
            )
            arrow_kwargs['patchA'] = node_patches[src_key]
            arrow_kwargs['patchB'] = node_patches[dst_key]

            arrow = patches.FancyArrowPatch(**arrow_kwargs)
            ax.add_patch(arrow)

    # --- Legend ------------------------------------------------------------------
    if show_legend:
        seen: Dict[str, str] = {}
        for li in layer_info:
            if li['name'] not in layer_node_keys:
                continue
            pt = li['pct_type']
            if pt not in seen:
                seen[pt] = li['color']
        handles = [
            patches.Patch(facecolor=c, edgecolor='black', label=t.capitalize())
            for t, c in seen.items()
        ]
        ax.legend(
            handles=handles,
            loc='upper right',
            fontsize=legend_fontsize,
            title='PCT Layer Type',
            title_fontsize=legend_title_fontsize,
        )

    plt.tight_layout(pad=2.0)
    if filename is not None:
        plt.savefig(filename, dpi=dpi, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    return fig


# %% ../nbs/03_visualization.ipynb #0988243c
import networkx as nx
import matplotlib.pyplot as plt
from typing import Optional, Tuple

def visualize_hierarchy_layers(
    individual,
    layout: str = 'spring', 
    show_weights: bool = False,
    save_path: Optional[str] = None,
    figsize: Tuple[int, int] = (12, 8)
) -> None:
    """
    Visualize the hierarchical layer structure using NetworkX graph.
    
    Creates a graph where each Keras layer is a node and connections
    between layers are edges. Different layout algorithms can be used
    to position nodes.
    
    Args:
        individual: DHPCTIndividual instance with compiled model
        layout: Graph layout algorithm ('spring', 'circular', 'shell', 'kamada_kawai')  
        show_weights: If True, show edge weights on connections
        save_path: Optional path to save the visualization
        figsize: Figure size as (width, height) tuple
        
    Raises:
        ValueError: If layout is not supported
        AttributeError: If individual doesn't have a compiled model
    """
    
    if not hasattr(individual, 'model') or individual.model is None:
        raise AttributeError("Individual must have a compiled Keras model")
    
    # Get layer information
    layer_info = _get_layer_info(individual.model)
    edges = _get_model_edges(individual.model)
    
    # Create NetworkX graph
    G = nx.DiGraph()
    
    # Add nodes with layer information
    for layer in layer_info:
        layer_type = _classify_layer(layer['name'])
        G.add_node(
            layer['name'],
            layer_type=layer_type,
            units=layer.get('units', 0),
            activation=layer.get('activation', 'none')
        )
    
    # Add edges
    for src, dst in edges:
        G.add_edge(src, dst)
        
    # Add weights to edges if requested
    if show_weights and hasattr(individual, 'model'):
        for src, dst in G.edges():
            try:
                # Try to get weight information from model
                src_layer = individual.model.get_layer(src)
                dst_layer = individual.model.get_layer(dst)
                
                # For weighted connections, get average absolute weight
                if hasattr(dst_layer, 'weights') and dst_layer.weights:
                    weights = dst_layer.get_weights()
                    if weights:
                        avg_weight = float(np.abs(weights[0]).mean())
                        G.edges[src, dst]['weight'] = avg_weight
                    else:
                        G.edges[src, dst]['weight'] = 0.0
                else:
                    G.edges[src, dst]['weight'] = 1.0
            except:
                G.edges[src, dst]['weight'] = 1.0
    
    # Set up the figure
    plt.figure(figsize=figsize)
    
    # Choose layout algorithm
    if layout == 'spring':
        pos = nx.spring_layout(G, k=3, iterations=50)
    elif layout == 'circular':
        pos = nx.circular_layout(G)
    elif layout == 'shell':
        pos = nx.shell_layout(G)
    elif layout == 'kamada_kawai':
        pos = nx.kamada_kawai_layout(G)
    else:
        raise ValueError(f"Unsupported layout: {layout}. Use 'spring', 'circular', 'shell', or 'kamada_kawai'")
    
    # Define colors for different layer types
    color_map = {
        'Input': '#E6E6FA',      # Light purple
        'Perception': '#ADD8E6',  # Light blue  
        'Reference': '#FF6B6B',   # Red
        'Comparator': '#FFD700',  # Amber/Gold
        'Output': '#90EE90',      # Light green
        'Actions': '#FFFF99',     # Yellow
        'Other': '#D3D3D3'        # Light gray
    }
    
    # Get node colors based on layer types
    node_colors = [color_map.get(G.nodes[node].get('layer_type', 'Other'), color_map['Other']) 
                   for node in G.nodes()]
    
    # Draw the graph
    nx.draw_networkx_nodes(G, pos, node_color=node_colors, 
                          node_size=800, alpha=0.9)
    
    # Draw edges with weights if requested
    if show_weights and any('weight' in G.edges[edge] for edge in G.edges()):
        # Get edge weights for width scaling
        edge_weights = [G.edges[edge].get('weight', 1.0) for edge in G.edges()]
        max_weight = max(edge_weights) if edge_weights else 1.0
        edge_widths = [2 * (w / max_weight) + 0.5 for w in edge_weights]
        
        nx.draw_networkx_edges(G, pos, width=edge_widths, alpha=0.6, 
                              edge_color='gray')
        
        # Draw edge labels with weights
        edge_labels = {edge: f"{G.edges[edge].get('weight', 0):.2f}" 
                      for edge in G.edges() if 'weight' in G.edges[edge]}
        nx.draw_networkx_edge_labels(G, pos, edge_labels, font_size=8)
    else:
        nx.draw_networkx_edges(G, pos, alpha=0.6, edge_color='gray')
    
    # Draw node labels
    nx.draw_networkx_labels(G, pos, font_size=10, font_weight='bold')
    
    # Add title and legend
    plt.title(f"Hierarchy Layers Visualization (Layout: {layout})", 
              fontsize=14, fontweight='bold')
    
    # Create legend for layer types
    legend_elements = []
    for layer_type, color in color_map.items():
        if any(G.nodes[node].get('layer_type', 'Other') == layer_type for node in G.nodes()):
            legend_elements.append(plt.Line2D([0], [0], marker='o', color='w', 
                                            markerfacecolor=color, markersize=10, 
                                            label=layer_type))
    
    if legend_elements:
        plt.legend(handles=legend_elements, loc='upper right', bbox_to_anchor=(1.1, 1))
    
    plt.tight_layout()
    
    # Save if path provided
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight')
    
    _show_or_close_figure()

# %% ../nbs/03_visualization.ipynb #2bd9a41d
def visualize_pct_units(
    individual,
    layout: str = 'spring',
    save_path: Optional[str] = None,
    figsize: Tuple[int, int] = (10, 8)
) -> None:
    """
    Visualize PCT hierarchy as functional units combining PL/RL/CL/OL per level.
    
    Creates a simplified graph where layers from the same hierarchy level
    are combined into single nodes representing PCT control units. This
    provides a cleaner view of the control structure.
    
    Args:
        individual: DHPCTIndividual instance with compiled model
        layout: Graph layout algorithm ('spring', 'circular', 'shell')
        save_path: Optional path to save the visualization
        figsize: Figure size as (width, height) tuple
        
    Raises:
        ValueError: If layout is not supported
        AttributeError: If individual doesn't have a compiled model
    """
    
    if not hasattr(individual, 'model') or individual.model is None:
        raise AttributeError("Individual must have a compiled Keras model")
    
    # Get layer information
    layer_info = _get_layer_info(individual.model)
    
    # Group layers by hierarchy level and function type
    pct_units = {}
    level_pattern = re.compile(r'([A-Z]+)(\d+)')
    
    for layer in layer_info:
        name = layer['name']
        
        # Parse layer name to identify PCT function and level
        match = level_pattern.search(name)
        if match:
            func_type = match.group(1)  # PL, RL, CL, OL
            level = int(match.group(2))  # Hierarchy level number
            
            unit_name = f"PCT_Unit_{level:02d}"
            
            if unit_name not in pct_units:
                pct_units[unit_name] = {
                    'level': level,
                    'functions': set(),
                    'layers': [],
                    'total_units': 0
                }
            
            pct_units[unit_name]['functions'].add(func_type)
            pct_units[unit_name]['layers'].append(name)
            pct_units[unit_name]['total_units'] += layer.get('units', 0)
        else:
            # Handle special layers (Observations, Actions, etc.)
            layer_type = _classify_layer(name)
            if layer_type in ['Input', 'Actions']:
                unit_name = layer_type
                if unit_name not in pct_units:
                    pct_units[unit_name] = {
                        'level': -1 if layer_type == 'Input' else 999,
                        'functions': {layer_type},
                        'layers': [name],
                        'total_units': layer.get('units', 0)
                    }
    
    # Create NetworkX graph with PCT units
    G = nx.DiGraph()
    
    # Add PCT unit nodes
    for unit_name, unit_data in pct_units.items():
        functions_str = '/'.join(sorted(unit_data['functions']))
        G.add_node(
            unit_name,
            level=unit_data['level'],
            functions=functions_str,
            layer_count=len(unit_data['layers']),
            total_units=unit_data['total_units']
        )
    
    # Create edges between PCT units based on hierarchy levels
    unit_names = list(pct_units.keys())
    
    # Sort units by level to create proper connections
    sorted_units = sorted([(name, data['level']) for name, data in pct_units.items() 
                          if data['level'] >= 0], key=lambda x: x[1])
    
    # Connect consecutive hierarchy levels
    for i in range(len(sorted_units) - 1):
        current_unit = sorted_units[i][0]
        next_unit = sorted_units[i + 1][0] 
        G.add_edge(current_unit, next_unit)
    
    # Connect Input to first PCT unit and last PCT unit to Actions
    if sorted_units:
        input_nodes = [name for name, data in pct_units.items() if 'Input' in data['functions']]
        action_nodes = [name for name, data in pct_units.items() if 'Actions' in data['functions']]
        
        first_pct = sorted_units[0][0]
        last_pct = sorted_units[-1][0]
        
        for input_node in input_nodes:
            G.add_edge(input_node, first_pct)
        
        for action_node in action_nodes:
            G.add_edge(last_pct, action_node)
    
    # Set up the figure
    plt.figure(figsize=figsize)
    
    # Choose layout algorithm  
    if layout == 'spring':
        pos = nx.spring_layout(G, k=2, iterations=50)
    elif layout == 'circular':
        pos = nx.circular_layout(G)
    elif layout == 'shell':
        # Create shells by hierarchy level
        shells = []
        for level in sorted(set(data['level'] for data in pct_units.values())):
            shell = [name for name, data in pct_units.items() if data['level'] == level]
            if shell:
                shells.append(shell)
        pos = nx.shell_layout(G, nlist=shells) if len(shells) > 1 else nx.spring_layout(G)
    else:
        raise ValueError(f"Unsupported layout: {layout}. Use 'spring', 'circular', or 'shell'")
    
    # Define colors for PCT units
    def get_unit_color(unit_data):
        functions = unit_data['functions']
        level = unit_data['level']
        
        if 'Input' in functions:
            return '#E6E6FA'  # Light purple
        elif 'Actions' in functions:
            return '#FFFF99'  # Yellow
        elif level >= 0:
            # Color PCT units by hierarchy level
            colors = ['#ADD8E6', '#90EE90', '#FFB6C1', '#DDA0DD', '#F0E68C', '#FFA07A']
            return colors[level % len(colors)]
        else:
            return '#D3D3D3'  # Gray
    
    # Get node colors and sizes
    node_colors = [get_unit_color(pct_units[node]) for node in G.nodes()]
    node_sizes = [300 + pct_units[node]['total_units'] * 10 for node in G.nodes()]
    
    # Draw the graph
    nx.draw_networkx_nodes(G, pos, node_color=node_colors, 
                          node_size=node_sizes, alpha=0.9)
    
    nx.draw_networkx_edges(G, pos, alpha=0.6, edge_color='gray',
                          arrows=True, arrowsize=20)
    
    # Create custom labels showing functions
    labels = {}
    for node in G.nodes():
        unit_data = pct_units[node]
        if 'PCT_Unit' in node:
            level = unit_data['level']
            functions = unit_data['functions']
            labels[node] = f"Level {level}\\n{'/'.join(sorted(functions))}"
        else:
            labels[node] = node
    
    nx.draw_networkx_labels(G, pos, labels, font_size=9, font_weight='bold')
    
    # Add title  
    plt.title(f"PCT Units Visualization (Layout: {layout})", 
              fontsize=14, fontweight='bold')
    
    # Create legend
    legend_elements = [
        plt.Line2D([0], [0], marker='o', color='w', markerfacecolor='#E6E6FA', 
                   markersize=10, label='Input'),
        plt.Line2D([0], [0], marker='o', color='w', markerfacecolor='#ADD8E6', 
                   markersize=10, label='PCT Level 0'),
        plt.Line2D([0], [0], marker='o', color='w', markerfacecolor='#90EE90', 
                   markersize=10, label='PCT Level 1'),
        plt.Line2D([0], [0], marker='o', color='w', markerfacecolor='#FFFF99', 
                   markersize=10, label='Actions')
    ]
    
    plt.legend(handles=legend_elements, loc='upper right', bbox_to_anchor=(1.15, 1))
    
    plt.tight_layout()
    
    # Save if path provided
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight')
    
    _show_or_close_figure()

