import matplotlib.cm as cm
from matplotlib.colors import Normalize

def visualize_weighted_network(
    individual,
    layout: str = 'spring',
    weight_threshold: float = 0.1,
    save_path: Optional[str] = None,
    figsize: Tuple[int, int] = (12, 10)
) -> None:
    """
    Visualize network with edge width and color proportional to weight magnitudes.
    
    Creates a detailed network visualization where connection strengths are
    visually represented through edge thickness and color intensity. Connections
    below the weight threshold are filtered out for clarity.
    
    Args:
        individual: DHPCTIndividual instance with compiled model
        layout: Graph layout algorithm ('spring', 'circular', 'shell', 'kamada_kawai')
        weight_threshold: Minimum weight magnitude to display (filters weak connections)
        save_path: Optional path to save the visualization  
        figsize: Figure size as (width, height) tuple
        
    Raises:
        ValueError: If layout is not supported or weight_threshold is negative
        AttributeError: If individual doesn't have a compiled model
    """
    
    if not hasattr(individual, 'model') or individual.model is None:
        raise AttributeError("Individual must have a compiled Keras model")
        
    if weight_threshold < 0:
        raise ValueError("weight_threshold must be non-negative")
    
    # Get layer information and model edges
    layer_info = _get_layer_info(individual.model)
    edges = _get_model_edges(individual.model)
    
    # Create NetworkX graph
    G = nx.DiGraph()
    
    # Add nodes
    for layer in layer_info:
        layer_type = _classify_layer(layer['name'])
        G.add_node(
            layer['name'],
            layer_type=layer_type,
            units=layer.get('units', 0)
        )
    
    # Collect all weight information
    edge_weights = {}
    
    for src, dst in edges:
        try:
            # Get the destination layer's weights
            dst_layer = individual.model.get_layer(dst)
            
            if hasattr(dst_layer, 'weights') and dst_layer.weights:
                weights = dst_layer.get_weights()
                if weights and len(weights) > 0:
                    # Calculate average absolute weight magnitude
                    weight_matrix = weights[0]  # First weight matrix (W, not bias)
                    avg_weight = float(np.abs(weight_matrix).mean())
                    max_weight = float(np.abs(weight_matrix).max())
                    edge_weights[(src, dst)] = {
                        'avg': avg_weight,
                        'max': max_weight,
                        'total': float(np.abs(weight_matrix).sum())
                    }
                else:
                    edge_weights[(src, dst)] = {'avg': 0.0, 'max': 0.0, 'total': 0.0}
            else:
                # No weights (e.g., activation layers) - assign default  
                edge_weights[(src, dst)] = {'avg': 1.0, 'max': 1.0, 'total': 1.0}
                
        except Exception as e:
            # Fallback for any errors in weight extraction
            edge_weights[(src, dst)] = {'avg': 0.0, 'max': 0.0, 'total': 0.0}
    
    # Filter edges based on weight threshold and add to graph
    filtered_edges = []
    for (src, dst), weight_data in edge_weights.items():
        avg_weight = weight_data['avg']
        if avg_weight >= weight_threshold:
            G.add_edge(src, dst, **weight_data)
            filtered_edges.append((src, dst))
    
    print(f"Displaying {len(filtered_edges)} edges above threshold {weight_threshold}")
    print(f"Filtered out {len(edges) - len(filtered_edges)} weak connections")
    
    if len(filtered_edges) == 0:
        print("Warning: No edges above threshold. Consider lowering weight_threshold.")
        return
    
    # Set up the figure  
    plt.figure(figsize=figsize)
    
    # Choose layout algorithm
    if layout == 'spring':
        pos = nx.spring_layout(G, k=3, iterations=50)
    elif layout == 'circular':
        pos = nx.circular_layout(G)
    elif layout == 'shell':
        pos = nx.shell_layout(G)
    elif layout == 'kamada_kawai':
        pos = nx.kamada_kawai_layout(G)
    else:
        raise ValueError(f"Unsupported layout: {layout}. Use 'spring', 'circular', 'shell', or 'kamada_kawai'")
    
    # Define colors for different layer types
    layer_color_map = {
        'Input': '#E6E6FA',      # Light purple
        'Perception': '#ADD8E6',  # Light blue  
        'Reference': '#FF6B6B',   # Red
        'Comparator': '#FFD700',  # Amber/Gold
        'Output': '#90EE90',      # Light green
        'Actions': '#FFFF99',     # Yellow
        'Other': '#D3D3D3'        # Light gray
    }
    
    # Get node colors and sizes
    node_colors = [layer_color_map.get(G.nodes[node].get('layer_type', 'Other'), 
                                      layer_color_map['Other']) for node in G.nodes()]
    node_sizes = [400 + G.nodes[node].get('units', 0) * 5 for node in G.nodes()]
    
    # Draw nodes
    nx.draw_networkx_nodes(G, pos, node_color=node_colors, 
                          node_size=node_sizes, alpha=0.9)
    
    # Prepare edge visualization based on weights
    if filtered_edges:
        # Get weight statistics for normalization  
        avg_weights = [G.edges[edge]['avg'] for edge in filtered_edges]
        min_weight = min(avg_weights)
        max_weight = max(avg_weights) 
        
        # Normalize weights for edge width (1 to 6 pixels)
        if max_weight > min_weight:
            edge_widths = [1 + 5 * (G.edges[edge]['avg'] - min_weight) / (max_weight - min_weight) 
                          for edge in filtered_edges]
        else:
            edge_widths = [3.0] * len(filtered_edges)
        
        # Create color map for edge weights (blue = weak, red = strong)
        norm = Normalize(vmin=min_weight, vmax=max_weight)
        cmap = plt.colormaps.get_cmap('coolwarm')  # Blue to red colormap
        edge_colors = [cmap(norm(G.edges[edge]['avg'])) for edge in filtered_edges]
        
        # Draw edges with proportional width and color
        nx.draw_networkx_edges(G, pos, edgelist=filtered_edges,
                              width=edge_widths, edge_color=edge_colors,
                              alpha=0.8, arrows=True, arrowsize=20)
        
        # Add colorbar for edge weights
        sm = plt.cm.ScalarMappable(cmap=cmap, norm=norm)
        sm.set_array([])
        cbar = plt.colorbar(sm, ax=plt.gca(), shrink=0.6)
        cbar.set_label('Average Weight Magnitude', rotation=270, labelpad=20)
    
    # Draw node labels
    nx.draw_networkx_labels(G, pos, font_size=9, font_weight='bold')
    
    # Add title
    plt.title(f"Weighted Network Visualization\\nLayout: {layout}, Threshold: {weight_threshold}", 
              fontsize=14, fontweight='bold')
    
    # Create legend for node types  
    legend_elements = []
    for layer_type, color in layer_color_map.items():
        if any(G.nodes[node].get('layer_type', 'Other') == layer_type for node in G.nodes()):
            legend_elements.append(plt.Line2D([0], [0], marker='o', color='w', 
                                            markerfacecolor=color, markersize=10, 
                                            label=layer_type))
    
    if legend_elements:
        plt.legend(handles=legend_elements, loc='upper left', bbox_to_anchor=(0, 1))
    
    # Add weight statistics text
    if filtered_edges:
        stats_text = f"Edges: {len(filtered_edges)}\\nWeight range: [{min_weight:.3f}, {max_weight:.3f}]"
        plt.text(0.02, 0.02, stats_text, transform=plt.gca().transAxes, 
                bbox=dict(boxstyle="round,pad=0.3", facecolor="white", alpha=0.8),
                verticalalignment='bottom', fontsize=10)
    
    plt.tight_layout()
    
    # Save if path provided
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight')
    
    _show_or_close_figure()

