def visualize_execution_history(
    history,
    metrics: List[str] = None,
    save_path: Optional[str] = None,
    figsize: Tuple[int, int] = (12, 8),
) -> None:
    """Plot time series of observations, actions, errors and rewards during execution.
    
    Args:
        history: ExecutionHistory object from individual.run(record_history=True)
        metrics: Which metrics to plot. Defaults to ["observations", "actions", "errors"].
            Supported values: "observations", "actions", "errors", "rewards",
            or "layer_NAME" for a specific layer's activations.
        save_path: If provided, save plot to file instead of displaying
        figsize: Figure size in inches (width, height)
        
    Raises:
        ValueError: If history is empty or a metric is unknown
    """
    if metrics is None:
        metrics = ["observations", "actions", "errors"]
    
    if len(history) == 0:
        raise ValueError("ExecutionHistory is empty — nothing to plot")
    
    n_plots = len(metrics)
    fig, axes = plt.subplots(n_plots, 1, figsize=figsize, sharex=True, squeeze=False)
    axes = axes[:, 0]  # flatten to 1D
    
    steps = np.arange(len(history))
    
    for ax, metric in zip(axes, metrics):
        if metric == "observations":
            if hasattr(history, "get_complete_observations_array"):
                data = history.get_complete_observations_array()
                obs_steps = np.arange(len(data))
            else:
                data = history.get_observations_array()
                obs_steps = steps
            ax.set_ylabel("Observations")
            if data.ndim == 2:
                for dim in range(data.shape[1]):
                    ax.plot(obs_steps, data[:, dim], label=f"obs[{dim}]", alpha=0.8)
                ax.legend(fontsize=7, loc="upper right")
            else:
                ax.plot(obs_steps, data)
        
        elif metric == "actions":
            data = history.get_actions_array()
            ax.set_ylabel("Actions")
            if data.ndim == 2:
                for dim in range(data.shape[1]):
                    ax.plot(steps, data[:, dim], label=f"act[{dim}]", alpha=0.8)
                ax.legend(fontsize=7, loc="upper right")
            else:
                ax.plot(steps, data)
        
        elif metric == "errors":
            data = history.get_errors_array()
            ax.set_ylabel("Errors")
            if data.ndim == 2:
                for dim in range(data.shape[1]):
                    ax.plot(steps, data[:, dim], label=f"err[{dim}]", alpha=0.8)
                ax.legend(fontsize=7, loc="upper right")
            else:
                ax.plot(steps, data)
        
        elif metric == "rewards":
            data = history.get_rewards_array()
            ax.set_ylabel("Rewards")
            ax.plot(steps, data, color="green")
            # Also show cumulative reward on secondary axis
            ax2 = ax.twinx()
            ax2.plot(steps, np.cumsum(data), color="orange", linestyle="--", alpha=0.6)
            ax2.set_ylabel("Cumulative", color="orange", fontsize=8)
            ax2.tick_params(axis="y", labelcolor="orange", labelsize=7)
        
        elif metric.startswith("layer_"):
            layer_name = metric[len("layer_"):]
            try:
                data = history.get_layer_activations_array(layer_name)
            except ValueError as e:
                raise ValueError(f"Unknown metric '{metric}': {e}")
            ax.set_ylabel(layer_name)
            if data.ndim == 2:
                for dim in range(data.shape[1]):
                    ax.plot(steps, data[:, dim], label=f"{layer_name}[{dim}]", alpha=0.8)
                ax.legend(fontsize=7, loc="upper right")
            else:
                ax.plot(steps, data)
        
        else:
            raise ValueError(
                f"Unknown metric '{metric}'. Supported: 'observations', 'actions', "
                f"'errors', 'rewards', or 'layer_NAME'"
            )
        
        ax.set_title(metric.replace("_", " ").title(), fontsize=10, fontweight="bold")
        ax.grid(True, alpha=0.3)
    
    axes[-1].set_xlabel("Time Step")
    fig.suptitle("Execution History", fontsize=13, fontweight="bold")
    plt.tight_layout()
    
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches="tight")
    
    _show_or_close_figure()


# %% ../nbs/03_visualization.ipynb #d9261ade
def visualize_layer_activations(
    history,
    layer_names: List[str],
    save_path: Optional[str] = None,
    figsize: Tuple[int, int] = (12, 6),
) -> None:
    """Plot activation values for specific layers over time as heatmaps and line plots.
    
    For each requested layer, shows a heatmap (rows=units, cols=timesteps) and
    a line plot of all units overlaid.
    
    Args:
        history: ExecutionHistory object
        layer_names: List of layer names to plot (e.g. ["PL00", "CL01"])
        save_path: If provided, save plot to file instead of displaying
        figsize: Figure size in inches (width, height)
        
    Raises:
        ValueError: If layer_names contains names not in the history
    """
    if len(history) == 0:
        raise ValueError("ExecutionHistory is empty — nothing to plot")
    
    available = list(history.layer_activations.keys())
    for name in layer_names:
        if name not in history.layer_activations:
            raise ValueError(
                f"Layer '{name}' not found in history. "
                f"Available layers: {available}"
            )
    
    n_layers = len(layer_names)
    fig, axes = plt.subplots(
        n_layers, 2, figsize=(figsize[0], figsize[1] * max(1, n_layers * 0.6)),
        squeeze=False,
    )
    
    steps = np.arange(len(history))
    
    for row, layer_name in enumerate(layer_names):
        data = history.get_layer_activations_array(layer_name)  # (steps, units)
        ax_heat = axes[row, 0]
        ax_line = axes[row, 1]
        
        # Heatmap
        im = ax_heat.imshow(
            data.T,
            aspect="auto",
            interpolation="nearest",
            cmap="RdBu_r",
            origin="lower",
        )
        ax_heat.set_ylabel(f"{layer_name}\nUnit")
        ax_heat.set_title(f"{layer_name} — Heatmap", fontsize=9, fontweight="bold")
        if row == n_layers - 1:
            ax_heat.set_xlabel("Time Step")
        plt.colorbar(im, ax=ax_heat, fraction=0.046, pad=0.04)
        
        # Line plot
        for unit in range(data.shape[1]):
            ax_line.plot(steps, data[:, unit], label=f"unit {unit}", alpha=0.8)
        ax_line.set_ylabel("Activation")
        ax_line.set_title(f"{layer_name} — Line Plot", fontsize=9, fontweight="bold")
        ax_line.grid(True, alpha=0.3)
        if data.shape[1] <= 10:
            ax_line.legend(fontsize=7, loc="upper right")
        if row == n_layers - 1:
            ax_line.set_xlabel("Time Step")
    
    fig.suptitle("Layer Activations Over Time", fontsize=13, fontweight="bold")
    plt.tight_layout()
    
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches="tight")
    
    _show_or_close_figure()

# %% ../nbs/03_visualization.ipynb #99b822c7
def visualize_error_propagation(
    history,
    save_path: Optional[str] = None,
    figsize: Tuple[int, int] = (12, 6),
) -> None:
    """Visualize how error signals propagate across hierarchy levels.
    
    Shows error magnitudes at each level over time as a stacked area plot
    and a heatmap, highlighting the flow of error from low to high levels.
    
    Args:
        history: ExecutionHistory object
        save_path: If provided, save plot to file instead of displaying
        figsize: Figure size in inches (width, height)
        
    Raises:
        ValueError: If history is empty or contains no error data
    """
    if len(history) == 0:
        raise ValueError("ExecutionHistory is empty — nothing to plot")
    
    error_levels = history.get_error_levels()
    if not error_levels:
        raise ValueError("No error data available in history")
    
    steps = np.arange(len(history))
    level_names = sorted(error_levels.keys())
    
    # Compute RMS error magnitude per level at each step
    level_magnitudes = {}
    for name in level_names:
        data = error_levels[name]  # (steps, units)
        if data.ndim == 1:
            data = data.reshape(-1, 1)
        level_magnitudes[name] = np.sqrt(np.mean(data ** 2, axis=1))  # RMS per step
    
    fig, axes = plt.subplots(1, 2, figsize=figsize)
    
    # --- Left panel: Stacked area plot ---
    ax_area = axes[0]
    stacked_data = np.column_stack([level_magnitudes[n] for n in level_names])
    ax_area.stackplot(
        steps,
        stacked_data.T,
        labels=level_names,
        alpha=0.7,
    )
    ax_area.set_xlabel("Time Step")
    ax_area.set_ylabel("RMS Error Magnitude")
    ax_area.set_title("Error Propagation (Stacked)", fontsize=10, fontweight="bold")
    ax_area.legend(fontsize=8, loc="upper right")
    ax_area.grid(True, alpha=0.3)
    
    # --- Right panel: Heatmap ---
    ax_heat = axes[1]
    heatmap_data = stacked_data.T  # (levels, steps)
    im = ax_heat.imshow(
        heatmap_data,
        aspect="auto",
        interpolation="nearest",
        cmap="hot_r",
        origin="lower",
    )
    ax_heat.set_xlabel("Time Step")
    ax_heat.set_ylabel("Level")
    ax_heat.set_yticks(range(len(level_names)))
    ax_heat.set_yticklabels(level_names)
    ax_heat.set_title("Error Magnitude Heatmap", fontsize=10, fontweight="bold")
    plt.colorbar(im, ax=ax_heat, fraction=0.046, pad=0.04, label="RMS Error")
    
    fig.suptitle("Error Propagation Across Hierarchy Levels", fontsize=13, fontweight="bold")
    plt.tight_layout()
    
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches="tight")
    
    _show_or_close_figure()
